from collections import deque

class Graph:
    def __init__(self):
        self.graph = {}

    def add_edge(self, u, v):
        if u not in self.graph:
            self.graph[u] = []
        self.graph[u].append(v)

    def dfs(self, start_node):
        visited = set()
        stack = deque([start_node])
        while stack:
            node = stack.popleft()
            if node not in visited:
                visited.add(node)
                print(f"Visiting node: {node}")
                yield node
                for neighbor in self.graph[node]:
                    if neighbor not in visited:
                        stack.append(neighbor)

    def bfs(self, start_node):
        visited = set()
        queue = deque([start_node])
        while queue:
            node = queue.popleft()
            if node not in visited:
                visited.add(node)
                print(f"Visiting node: {node}")
                yield node
                for neighbor in self.graph[node]:
                    if neighbor not in visited:
                        queue.append(neighbor)

def a_star(graph, start_node, goal_node):
    """
    Finds the shortest path between start_node and goal_node using A* search algorithm.

    Args:
        graph: A graph object.
        start_node: The starting node.
        goal_node: The goal node.

    Returns:
        A list of nodes representing the shortest path, or None if no path is found.
    """
    open_set = deque()
    open_set.append((0, start_node))  # (distance, node)
    closed_set = set()

    while open_set:
        current_distance, current_node = open_set.popleft()

        if current_node == goal_node:
            return reconstruct_path(graph, current_node)  # Reconstruct path

        closed_set.add(current_node)  

        for neighbor in graph.graph[current_node]:
            distance = current_distance + 1  # Assuming we want to move to adjacent nodes. 
            if neighbor in closed_set:
                continue
            if neighbor not in open_set:
                open_set.append((distance, neighbor))

    return None


def reconstruct_path(graph, node):
    path = []
    while node is not None:
        path.append(node)
        node = graph.graph[node]
    return path[::-1]


