class AStar:
    def __init__(self, heuristic, start, goal):
        self.heuristic = heuristic  
        self.start = start
        self.goal = goal

    def get_neighbors(self, node):
        neighbors = defaultdict(list)
        for direction in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
            x, y = node[0] + direction[0], node[1] + direction[1]
            if 0 <= x < len(self.grid) and 0 <= y < len(self.grid[0]):
                neighbors[direction] = [self.grid[x][y]]
        return neighbors

    def find_path(self):
        # Initialize open and closed lists
        open_set = [(0, self.start)]  # Priority: shorter distances
        closed_set = set()

        while open_set:
            # Get node with lowest cost (priority)
            current_cost, current_node = min(open_set, key=lambda x: x[0])
            open_set.remove(current_node)
            closed_set.add(current_node)

            # Check if we reached the goal
            if current_node == self.goal:
                return self._construct_path(current_node)

            for direction, neighbor in self.get_neighbors(current_node):
                # Calculate tentative cost
                tentative_cost = current_cost + self.distance_cost(current_node, neighbor)

                # Add neighbor to open list with new tentative cost 
                if neighbor not in closed_set:
                    neighbor_cost = tentative_cost + self.heuristic(neighbor, self.goal)
                    open_set.append((neighbor_cost, neighbor))

        return None  

    def distance_cost(self, current_node, neighbor):
        # Replace with your distance function 
        return abs(current_node[0] - neighbor[0]) + abs(current_node[1] - neighbor[1])

    def heuristic(self, node, goal):
        # Replace with your heuristic function 
        return abs(node[0] - goal[0]) + abs(node[1] - goal[1]) 

    def _construct_path(self, goal):
        # Reconstruct the path from the goal node back to the start
        path = [goal]
        current = goal
        while current != self.start:
            current = self.get_parent(current)
            path.append(current)
        path.reverse()  # Reverse the path to get the correct order

        return path

